await figma.setCurrentPageAsync(figma.getNodeById("7:2"));
const home=figma.getNodeById("19:2");
const hb=home.absoluteBoundingBox;
const hits=[];
function walk(n){try{if(n.type==="VECTOR"){const b=n.absoluteBoundingBox;const ry=b.y-hb.y,rx=b.x-hb.x;if(ry>85&&ry<140){hits.push({name:n.name,rx,ry,rw:b.width,rh:b.height});n.x+=308-rx;n.y+=104-ry;}}}catch(e){hits.push({err:String(e)});}if("children"in n){for(const c of n.children)walk(c);}}
walk(home);
return JSON.stringify(hits);
